-- ⚠️ DRAFT — NOT YET APPLIED TO PRODUCTION
--
-- Generated by the overnight schema audit. See OVERNIGHT_AUDIT.md
-- "Database schema + RLS audit", finding #1.
--
-- This migration enables RLS and adds per-user policies on 20 application
-- tables that currently have NO row-level security in their migration
-- history. Without RLS, any authenticated user can read/write all rows
-- across all companies on these tables.
--
-- Before applying:
--   1. Read each policy below carefully. The scope column (user_id,
--      property_id, company_id, etc.) may not match how YOUR app actually
--      reads the table. Adjust the USING clause per-table.
--   2. Some tables (e.g. admin_announcements, feature_flag_*) are
--      INTENTIONALLY readable by all signed-in users. For those, the
--      policy should be `USING (auth.role() = 'authenticated')` not the
--      ownership check below.
--   3. Some tables hold tenant data (tenant_messages, tenant_profiles).
--      Tenants reading their own data + landlords reading any tenant on
--      their property is a more complex policy than the default below.
--   4. Apply on a staging branch first — Supabase has a "preview branch"
--      feature that's safer than applying to prod directly.
--
-- This file is named with a leading underscore so it doesn't run via
-- `supabase db push`. Rename to drop the underscore once reviewed.

-- ── Helper assumptions ─────────────────────────────────────────────────
-- All policies below assume the following functions already exist (they
-- do — defined in row-level-security.sql):
--   is_developer()                  → bool
--   has_company_access(uuid)        → bool  -- user owns or has shared
--                                              access to the company
--   has_property_access(uuid)       → bool  -- via the property's company

-- ────────────────────────────────────────────────────────────────────────
-- USER-SCOPED tables (user_id column on the row)
-- ────────────────────────────────────────────────────────────────────────

-- property_notes — per-property notes left by landlords
alter table public.property_notes enable row level security;
drop policy if exists "property_notes_all" on public.property_notes;
create policy "property_notes_all" on public.property_notes for all
  using (is_developer() or user_id = auth.uid() or has_property_access(property_id))
  with check (is_developer() or user_id = auth.uid() or has_property_access(property_id));

-- referrals — user's own referral records
alter table public.referrals enable row level security;
drop policy if exists "referrals_all" on public.referrals;
create policy "referrals_all" on public.referrals for all
  using (is_developer() or user_id = auth.uid())
  with check (is_developer() or user_id = auth.uid());

-- address_book — user's saved contractors / contacts
alter table public.address_book enable row level security;
drop policy if exists "address_book_all" on public.address_book;
create policy "address_book_all" on public.address_book for all
  using (is_developer() or user_id = auth.uid())
  with check (is_developer() or user_id = auth.uid());

-- admin_notes — admin's own internal notes about other users
alter table public.admin_notes enable row level security;
drop policy if exists "admin_notes_select" on public.admin_notes;
create policy "admin_notes_select" on public.admin_notes for select
  using (is_developer());
drop policy if exists "admin_notes_insert" on public.admin_notes;
create policy "admin_notes_insert" on public.admin_notes for insert
  with check (is_developer());
drop policy if exists "admin_notes_update" on public.admin_notes;
create policy "admin_notes_update" on public.admin_notes for update
  using (is_developer());
drop policy if exists "admin_notes_delete" on public.admin_notes;
create policy "admin_notes_delete" on public.admin_notes for delete
  using (is_developer());

-- invitations — per-email invites a user has issued
alter table public.invitations enable row level security;
drop policy if exists "invitations_select" on public.invitations;
create policy "invitations_select" on public.invitations for select
  using (is_developer() or invited_by = auth.uid() or email = auth.email());
drop policy if exists "invitations_insert" on public.invitations;
create policy "invitations_insert" on public.invitations for insert
  with check (invited_by = auth.uid());
drop policy if exists "invitations_update" on public.invitations;
create policy "invitations_update" on public.invitations for update
  using (is_developer() or invited_by = auth.uid() or email = auth.email());
drop policy if exists "invitations_delete" on public.invitations;
create policy "invitations_delete" on public.invitations for delete
  using (is_developer() or invited_by = auth.uid());

