-- ────────────────────────────────────────────────────────────────────────
-- COMPANY-SCOPED tables (company_id → joins to company access)
-- ────────────────────────────────────────────────────────────────────────

-- subscriptions — Stripe subscription per company
alter table public.subscriptions enable row level security;
drop policy if exists "subscriptions_select" on public.subscriptions;
create policy "subscriptions_select" on public.subscriptions for select
  using (is_developer() or has_company_access(company_id));
-- Only service role / webhooks should INSERT/UPDATE billing rows.
-- (No INSERT/UPDATE policy = client cannot modify — service_role bypasses)
drop policy if exists "subscriptions_delete" on public.subscriptions;
create policy "subscriptions_delete" on public.subscriptions for delete
  using (is_developer());

-- company_documents — files attached at the company level
alter table public.company_documents enable row level security;
drop policy if exists "company_documents_all" on public.company_documents;
create policy "company_documents_all" on public.company_documents for all
  using (is_developer() or has_company_access(company_id))
  with check (is_developer() or has_company_access(company_id));

-- ────────────────────────────────────────────────────────────────────────
-- INSURANCE — policies + join table
-- ────────────────────────────────────────────────────────────────────────

alter table public.insurance_policies enable row level security;
drop policy if exists "insurance_policies_all" on public.insurance_policies;
create policy "insurance_policies_all" on public.insurance_policies for all
  using (is_developer() or user_id = auth.uid() or has_company_access(company_id))
  with check (is_developer() or user_id = auth.uid() or has_company_access(company_id));

-- The join table — gated by access to the policy itself
alter table public.insurance_policy_properties enable row level security;
drop policy if exists "insurance_policy_properties_all" on public.insurance_policy_properties;
create policy "insurance_policy_properties_all" on public.insurance_policy_properties for all
  using (
    is_developer() or exists (
      select 1 from public.insurance_policies p
      where p.id = policy_id
      and (p.user_id = auth.uid() or has_company_access(p.company_id))
    )
  )
  with check (
    is_developer() or exists (
      select 1 from public.insurance_policies p
      where p.id = policy_id
      and (p.user_id = auth.uid() or has_company_access(p.company_id))
    )
  );

