-- ────────────────────────────────────────────────────────────────────────
-- TENANT-FACING tables — more nuanced: tenant reads own, landlord reads any
-- ────────────────────────────────────────────────────────────────────────

-- tenant_profiles — a tenant's profile (linked to a property + auth user)
alter table public.tenant_profiles enable row level security;
drop policy if exists "tenant_profiles_select" on public.tenant_profiles;
create policy "tenant_profiles_select" on public.tenant_profiles for select
  using (
    is_developer()
    or user_id = auth.uid()                    -- the tenant themselves
    or has_property_access(property_id)        -- the landlord
  );
drop policy if exists "tenant_profiles_insert" on public.tenant_profiles;
create policy "tenant_profiles_insert" on public.tenant_profiles for insert
  with check (user_id = auth.uid() or has_property_access(property_id));
drop policy if exists "tenant_profiles_update" on public.tenant_profiles;
create policy "tenant_profiles_update" on public.tenant_profiles for update
  using (
    is_developer()
    or user_id = auth.uid()
    or has_property_access(property_id)
  );
drop policy if exists "tenant_profiles_delete" on public.tenant_profiles;
create policy "tenant_profiles_delete" on public.tenant_profiles for delete
  using (is_developer() or has_property_access(property_id));

-- tenant_messages — messages between tenant and landlord
alter table public.tenant_messages enable row level security;
drop policy if exists "tenant_messages_select" on public.tenant_messages;
create policy "tenant_messages_select" on public.tenant_messages for select
  using (
    is_developer()
    or sender_id = auth.uid()
    or recipient_id = auth.uid()
    or has_property_access(property_id)
  );
drop policy if exists "tenant_messages_insert" on public.tenant_messages;
create policy "tenant_messages_insert" on public.tenant_messages for insert
  with check (sender_id = auth.uid());
drop policy if exists "tenant_messages_update" on public.tenant_messages;
create policy "tenant_messages_update" on public.tenant_messages for update
  using (
    is_developer()
    or sender_id = auth.uid()
    or recipient_id = auth.uid()
    or has_property_access(property_id)
  );
drop policy if exists "tenant_messages_delete" on public.tenant_messages;
create policy "tenant_messages_delete" on public.tenant_messages for delete
  using (is_developer() or sender_id = auth.uid());

-- ────────────────────────────────────────────────────────────────────────
-- PUBLIC-READABLE tables — broadcast content for all signed-in users
-- ────────────────────────────────────────────────────────────────────────

-- admin_announcements — platform-wide announcements shown in the banner.
-- All authenticated users can READ; only developers can write.
alter table public.admin_announcements enable row level security;
drop policy if exists "admin_announcements_select" on public.admin_announcements;
create policy "admin_announcements_select" on public.admin_announcements for select
  using (auth.role() = 'authenticated');
drop policy if exists "admin_announcements_insert" on public.admin_announcements;
create policy "admin_announcements_insert" on public.admin_announcements for insert
  with check (is_developer());
drop policy if exists "admin_announcements_update" on public.admin_announcements;
create policy "admin_announcements_update" on public.admin_announcements for update
  using (is_developer());
drop policy if exists "admin_announcements_delete" on public.admin_announcements;
create policy "admin_announcements_delete" on public.admin_announcements for delete
  using (is_developer());

